WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_grass_g_reverse'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '生长量反求', 'kp-grass-g-reverse', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "生长量反求"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心绝招：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "利用差值法秒杀草速 X。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不需要列出两个方程慢慢解 Y。草速 X 就是两人吃的草的总量差除以时间差。"}]}, {"type": "katexBlock", "attrs": {"content": "X = \\frac{N_1 \\times T_1 - N_2 \\times T_2}{T_1 - T_2}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 10头牛吃20天(共消耗200份)，15头牛吃10天(共消耗150份)。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这 10 天的时间差里，多出了 200 - 150 = 50 份草。说明每天新长出的草 X = 50 / 10 = 5 份！秒杀。"}]}]}$$ AS jsonb), NULL, '生长量反求的核心考点与实战推导。', category_node.id, CAST('["数量关系", "牛吃草问题", "生长量反求"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_grass_g_reverse", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
